            aOrbiterG = (aWandererK + RotL64(aCross, 13U)) + 0x31A5F81AD8FD21D5ULL;
            aOrbiterB = (aWandererB + RotL64(aPrevious, 47U)) + 0xE8CE38449BA65B41ULL;
            aOrbiterE = (aWandererC + RotL64(aIngress, 3U)) + 0xEE0E969FAFA6F4BAULL;
            aOrbiterC = ((aWandererJ + RotL64(aScatter, 35U)) + 0xA646060F8E8A9619ULL) + aTwistOrbiterAssignSaltC[((aIndex + 15U)) & S_SALT1];
