            aOrbiterE = RotL64((aOrbiterE * 0x3A557A6A91FBA9F5ULL), 43U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterH) + 0x04E9CE267737F226ULL) + aTwistOrbiterUpdateSaltB[((aIndex + 21U)) & S_SALT1];
