            aOrbiterD = (aOrbiterD + aOrbiterE) + 0xC57261E970D57A20ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterD) ^ 0xA3EBA4DB6A236CE2ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xAB163E3777B85A23ULL), 21U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0xEF4BDEDB892BF462ULL;
