            //
            aIngress = (RotL64(aWindLaneA[((aIndex + 6700U)) & S_BLOCK1], 54U) ^ RotL64(aWindLaneB[((aIndex + 508U)) & S_BLOCK1], 3U));
            aIngress ^= (RotL64(aWoodLaneB[((aIndex + 6943U)) & S_BLOCK1], 43U) ^ RotL64(aLightningLaneB[((aIndex + 6601U)) & S_BLOCK1], 21U));
            aIngress = TwistMix64::DiffuseA((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneC[((S_BLOCK1 - aIndex + 5471U)) & S_BLOCK1], 44U) ^ RotL64(aShadowLaneC[((S_BLOCK1 - aIndex + 5645U)) & S_BLOCK1], 21U));
            aCross ^= (RotL64(aShadowLaneD[((S_BLOCK1 - aIndex + 6452U)) & S_BLOCK1], 29U) ^ RotL64(aPoisonLaneC[((S_BLOCK1 - aIndex + 2435U)) & S_BLOCK1], 11U));
            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCross, 41U) ^ RotL64(aIngress, 57U)) ^ (RotL64(aPrevious, 5U) + RotL64(aCarry, 28U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterG = (aWandererF + RotL64(aIngress, 29U)) + 0x5E7384F256E13B25ULL;
            aOrbiterH = ((aWandererG + RotL64(aPrevious, 39U)) + RotL64(aCarry, 39U)) + 0xD4B12DF460C28853ULL;
            aOrbiterE = (aWandererK + RotL64(aCross, 11U)) + 0x162A5CA6503196F9ULL;
            aOrbiterD = (((aWandererC + RotL64(aScatter, 47U)) + RotL64(aCarry, 13U)) + 0x682685C553DF7489ULL) + aKeyRotateAOrbiterAssignSaltC[((aIndex + 8U)) & S_SALT1];
            aOrbiterA = ((aWandererE + RotL64(aCross, 3U)) + RotL64(aCarry, 53U)) + 0xEB2C3CCA98CEEC87ULL;
            aOrbiterB = (aWandererI + RotL64(aPrevious, 21U)) + 0x35A4490F188B0908ULL;
            aOrbiterC = ((aWandererB + RotL64(aIngress, 56U)) + 0xBA59B2DD7F01149EULL) + aKeyRotateAOrbiterAssignSaltE[(((31U - aIndex) + 17U)) & S_SALT1];
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0xF0E8F7C2305635E3ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterG) ^ 0x2BE613A2F74770F2ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x5E8529A4A225088BULL), 27U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterA) + 0x26344FD29E697C35ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0x768CA5556A31EEC6ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x36D038CB45DEBB77ULL), 41U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterB) + 0x3BC4A7EA8DD52ABFULL) + aKeyRotateAOrbiterUpdateSaltA[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterE) ^ 0x0542D39CBA1DD2BAULL;
            aOrbiterD = RotL64((aOrbiterD * 0x2DC82885D6191D53ULL), 5U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterC) + 0xBB737B476E21EEE9ULL) + aKeyRotateAOrbiterUpdateSaltB[((aIndex + 25U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterH) ^ 0x16ADEBD7DCE7C2C2ULL) ^ aKeyRotateAOrbiterUpdateSaltD[((aIndex + 5U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xA4319A7BD5F37795ULL), 11U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0xB955420FEAB770C5ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterB) ^ 0x28FA3C28DD8B3FA9ULL) ^ aKeyRotateAOrbiterUpdateSaltF[((aIndex + 29U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x69A3F337706768D9ULL), 57U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterE) + 0x221EE89AC15F2204ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterA) ^ 0x4AEEF54296CCB896ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x5496F10157E9F2A7ULL), 19U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterD) + 0x7920CD83C741C2F9ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0x1FC93CCB44DA06BFULL;
            aOrbiterG = RotL64((aOrbiterG * 0x3CFE1F8469D24979ULL), 51U);
            //
            aIngress = aOrbiterG ^ RotL64(aOrbiterA, 43U);
            aIngress = aIngress + (aOrbiterH ^ RotL64(aOrbiterD, 14U));
            aIngress = aIngress + (aOrbiterE ^ RotL64(aOrbiterB, 23U));
            aIngress = aIngress + RotL64(aOrbiterC, 3U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererC = aWandererC + (((RotL64(aPrevious, 38U) + RotL64(aOrbiterD, 29U)) + aOrbiterH) + RotL64(aCarry, 37U));
            aWandererK = aWandererK ^ (((RotL64(aIngress, 57U) + RotL64(aOrbiterB, 13U)) + aOrbiterG) + aKeyRotateAWandererUpdateSaltD[((aIndex + 14U)) & S_SALT1]);
            aWandererI = aWandererI + ((RotL64(aCross, 29U) + RotL64(aOrbiterH, 23U)) + aOrbiterC);
            aWandererG = aWandererG ^ (((RotL64(aScatter, 3U) + aOrbiterA) + RotL64(aOrbiterC, 37U)) + aKeyRotateAWandererUpdateSaltF[(((31U - aIndex) + 22U)) & S_SALT1]);
            aWandererB = aWandererB + (((RotL64(aCross, 51U) + RotL64(aOrbiterC, 54U)) + aOrbiterG) + RotL64(aCarry, 13U));
            aWandererF = aWandererF ^ ((RotL64(aScatter, 19U) + RotL64(aOrbiterD, 5U)) + aOrbiterA);
            aWandererE = aWandererE + ((RotL64(aIngress, 11U) + RotL64(aOrbiterE, 43U)) + aOrbiterD);
            //
            aCarry = aCarry + (aWandererK ^ RotL64(aWandererC, 30U));
