            aOrbiterD = ((aWandererF + RotL64(aIngress, 47U)) + 0xCD491F0FBF8340D7ULL) + aKeyRotateBOrbiterAssignSaltE[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterA = ((aWandererB + RotL64(aPrevious, 13U)) + RotL64(aCarry, 5U)) + 0x0E415C1233A40C3CULL;
